/// <summary>
/// Hand-rolled CSV writer for order exports.
/// </summary>
/// <remarks>
/// Trade-off: We rejected CsvHelper because we need exact
/// control over RFC 4180 quoting for our European customers
/// who use semicolons as delimiters. CsvHelper supports this,
/// but adds 200KB to the deployment and introduces a
/// dependency we would need to patch for our edge cases.
/// Hand-rolling keeps the dependency footprint at zero and
/// makes the quoting behavior fully auditable, at the cost
/// of maintaining this class ourselves.
/// </remarks>
public class OrderCsvWriter
{
    private readonly TextWriter _writer;
    private readonly string _delimiter;

    public OrderCsvWriter(TextWriter writer, string delimiter = ",")
    {
        _writer = writer;
        _delimiter = delimiter;
    }

    public async Task WriteAsync(IEnumerable<Order> orders)
    {
        await _writer.WriteLineAsync("OrderId,Date,Total,Status");
        foreach (var order in orders)
        {
            var line = $"{order.Id},{order.Date:O},"{Escape(order.Total)}",{Escape(order.Status)}";
            await _writer.WriteLineAsync(line);
        }
        await _writer.FlushAsync();
    }

    private string Escape(string value)
    {
        if (value.Contains(_delimiter) || value.Contains('"'))
            return $"""{value.Replace("""""""", """"""""")}""";
        return value;
    }
}
